def _s(x):
    try:
        return x if isinstance(x, str) else ("" if x is None else str(x))
    except Exception:
        return ""


def _entries(snap, prefix, typ):
    """Yield (suffix, value) for keys with a prefix and a given redis type."""
    out = {}
    if not isinstance(snap, dict):
        return out
    for k, e in snap.items():
        if not isinstance(k, str) or not k.startswith(prefix) or not isinstance(e, dict):
            continue
        if e.get("t") != typ:
            continue
        out[k[len(prefix):]] = e.get("v")
    return out


def _members(v):
    res = []
    if isinstance(v, list):
        for m in v:
            if isinstance(m, (list, tuple)) and m:
                res.append(_s(m[0]))
            elif isinstance(m, str):
                res.append(m)
    return res


def _job_of(entry):
    return entry.split(":")[0]


def _state(snap):
    jobs = {}
    for suffix, v in _entries(snap, "rq:job:", "hash").items():
        if ":" in suffix or not isinstance(v, dict):
            continue
        jobs[suffix] = v

    queues = {}
    for name, v in _entries(snap, "rq:queue:", "list").items():
        if name.endswith(":intermediate"):
            continue
        queues[name] = [_s(x) for x in v] if isinstance(v, list) else []

    regs = {}
    for label, prefix in (("started", "rq:wip:"), ("finished", "rq:finished:"),
                          ("failed", "rq:failed:"), ("deferred", "rq:deferred:"),
                          ("scheduled", "rq:scheduled:"), ("canceled", "rq:canceled:")):
        d = {}
        for name, v in _entries(snap, prefix, "zset").items():
            d[name] = [_job_of(m) for m in _members(v)]
        regs[label] = d

    workers = {}
    for name, v in _entries(snap, "rq:worker:", "hash").items():
        if isinstance(v, dict):
            workers[name] = v

    results = {}
    for jid, v in _entries(snap, "rq:results:", "stream").items():
        results[jid] = v if isinstance(v, list) else []

    execs = {}
    for jid, v in _entries(snap, "rq:executions:", "zset").items():
        execs[jid] = _members(v)

    return jobs, queues, regs, workers, results, execs


_RESULT_TYPES = {"1": "successful", "2": "failed", "3": "stopped", "4": "retried", "5": "max_retries_exceeded"}


def abstract(snap):
