        len(ids) == len(set(ids)) for ids in queues.values())
    inv["a job is not waiting in two queues"] = len({j for _, j in all_q}) == len(all_q)
    inv["every queued job exists and has status queued"] = all(
        j in jobs and _s(jobs[j].get("status")) == "queued" for _, j in all_q)
    inv["queued jobs wait in the queue they were enqueued to"] = all(
        j not in jobs or _s(jobs[j].get("origin")) in ("", q) for q, j in all_q)

    def reg_ok(label, status_set):
        for q, ids in regs[label].items():
            for j in ids:
                if j in jobs and _s(jobs[j].get("status")) not in status_set:
                    return False
        return True

    inv["finished registry holds only finished jobs"] = reg_ok("finished", {"finished"})
    inv["failed registry holds only failed or stopped jobs"] = reg_ok("failed", {"failed", "stopped"})
    inv["deferred registry holds only deferred jobs"] = reg_ok("deferred", {"deferred"})
    inv["scheduled registry holds only scheduled jobs"] = reg_ok("scheduled", {"scheduled"})
    inv["started registry holds only started jobs"] = reg_ok("started", {"started"})

    inv["a started job is not also waiting in a queue"] = all(
        j not in {x for ids in regs["started"].values() for x in ids} for _, j in all_q)
    inv["a started job has a worker"] = all(
        _s(h.get("worker_name")) != "" for h in jobs.values() if _s(h.get("status")) == "started")
    inv["a started job has a start time"] = all(
        _s(h.get("started_at")) != "" for h in jobs.values() if _s(h.get("status")) == "started")
    inv["a finished job has an end time"] = all(
        _s(h.get("ended_at")) != "" for h in jobs.values() if _s(h.get("status")) == "finished")
    inv["every job has a known status"] = all(
        _s(h.get("status")) in ("created", "queued", "finished", "failed", "started",
                                "deferred", "scheduled", "stopped", "canceled")
        for h in jobs.values())

    inv["an idle worker has no current job"] = all(
        not _s(h.get("current_job")) for h in workers.values() if _s(h.get("state")) == "idle")
    inv["a busy worker has a current job"] = all(
        bool(_s(h.get("current_job"))) for h in workers.values() if _s(h.get("state")) == "busy")

    def nonneg(h, f):
        v = _s(h.get(f))
        if v == "":
            return True
        try:
            return int(v) >= 0
        except Exception:
            return False

    inv["worker job counts are non-negative numbers"] = all(
        nonneg(h, "successful_job_count") and nonneg(h, "failed_job_count") for h in workers.values())

    inv["a job keeps at most 10 results"] = all(len(r) <= 10 for r in results.values())
    inv["a job with a running execution is started or being finished"] = all(
        (j not in jobs) or _s(jobs[j].get("status")) in ("started", "finished", "failed", "stopped", "queued", "scheduled")
        for j, m in execs.items() if m)
    return inv
